import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.C9sp7nFj.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1778457209000}'),n={name:"guide/getting-started.md"};function r(o,e,l,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>pika</strong> is a self-hosted server that combines three things into a single binary:</p><ol><li><strong>A configuration store</strong> — versioned JSON / YAML / TOML configs with per-environment variants and rich inheritance from external sources.</li><li><strong>A secrets manager</strong> — encryption at rest with key rotation, plus integrations for pulling values from Vault, Kubernetes, cloud secret managers, and more.</li><li><strong>A raw file server</strong> — mount local disks, S3, FTP/SFTP, WebDAV, or Vercel Blob and expose them over HTTP, FTP, SFTP, TFTP, or WebDAV.</li></ol><p>Everything is administered through a built-in web UI; consumers fetch resolved data over a small, well-defined HTTP API.</p><h2 id="why-pika" tabindex="-1">Why pika? <a class="header-anchor" href="#why-pika" aria-label="Permalink to &quot;Why pika?&quot;">​</a></h2><ul><li><strong>One binary.</strong> No external database, no companion process — pika ships with an embedded <a href="https://github.com/rakunlabs/bw" target="_blank" rel="noreferrer">bw</a> (BadgerDB) store. Mount a single volume, point it at a port, done.</li><li><strong>Edit-aware.</strong> Every save is versioned. You can roll back, diff, or pin a consumer to a specific version using either an integer or a semver constraint.</li><li><strong>Inheritance instead of templating.</strong> Compose a final config out of pieces sourced from Vault, Kubernetes, S3, Consul, etcd, AWS Secrets Manager / SSM, GCP Secret Manager, Azure Key Vault, plain HTTP, or other pika files — without macros or templating languages.</li><li><strong>Hot reload.</strong> Authentication strategies, hooks, raw mounts, and external sources are managed at runtime from the UI. No restart needed.</li><li><strong>Cluster-ready.</strong> Run a 3+ node HA cluster with QUIC-based peer discovery, leader-elected writes, and replicated reads.</li></ul><h2 id="try-it-in-30-seconds" tabindex="-1">Try it in 30 seconds <a class="header-anchor" href="#try-it-in-30-seconds" aria-label="Permalink to &quot;Try it in 30 seconds&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pika</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pika:/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ghcr.io/rakunlabs/pika:latest</span></span></code></pre></div><p>Open <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a>, create the initial admin account, and you have a working server.</p><p>To consume a config, create a file in the UI, then mint an API token under <strong>Settings → Tokens</strong> and read it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer pika_...&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/data/myapp/config</span></span></code></pre></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./installation">Installation</a> — Docker, Kubernetes, or a static binary.</li><li><a href="./configuration">Configuration</a> — environment variables and the YAML config file.</li><li><a href="./concepts">Concepts</a> — folders, configs, versions, variants, and inheritance.</li><li><a href="/reference/consuming-data">Consuming data</a> — the <code>/data/*</code> endpoint, authentication, and query parameters.</li><li><a href="/reference/api">Admin API</a> — the full REST surface for management operations.</li></ul><h2 id="project-status" tabindex="-1">Project status <a class="header-anchor" href="#project-status" aria-label="Permalink to &quot;Project status&quot;">​</a></h2><p>Pika is actively developed at <a href="https://github.com/rakunlabs/pika" target="_blank" rel="noreferrer">rakunlabs/pika</a>. Issues and pull requests are welcome.</p>',15)])])}const u=a(n,[["render",r]]);export{g as __pageData,u as default};
